declarations.type_as_printed_by_lean:
@ZeroFree.LocalShape.surplus_pos : ∀ {p z : ℝ},
  ZeroFree.LocalShape.pLo ≤ p →
    p ≤ ZeroFree.LocalShape.pHi → 0 ≤ z → z ≤ ZeroFree.LocalShape.zHi → 0 < ZeroFree.LocalShape.surplus p z

@ZeroFree.LocalShape.zero_height_bounds : ∀ {t : ℝ},
  |t - ZeroFree.LocalShape.heightC| ≤ 1 / 200 →
    0 ≤ ZeroFree.LocalShape.zeroHeightSquare t ∧ ZeroFree.LocalShape.zeroHeightSquare t ≤ ZeroFree.LocalShape.zHi

@ZeroFree.LocalShape.finite_weighted_kernel_bound : ∀ {ι : Type u_1} (anchors : Finset ι) (weight value budget : ι → ℝ),
  (∀ j ∈ anchors, 0 ≤ weight j) →
    (∀ j ∈ anchors, value j ≤ budget j) → ∑ j ∈ anchors, weight j * value j ≤ ∑ j ∈ anchors, weight j * budget j
